def parse_xml(data):
    root = ET.fromstring(data)
    seq = None
    try:
        seq = int(root.get("seq"))
    except (TypeError, ValueError):
        pass
    root_unit = norm_unit(root.get("weight-unit") or root.get("weight_unit") or root.get("unit"))
    records = []
    for sh in root.iter("shipment"):
        def get(name):
            if sh.get(name) is not None:
                return sh.get(name)
            el = sh.find(name)
            return el.text if el is not None and el.text is not None else None
        num = shipment_number(sh.get("id") or get("id"))
        if num is None:
            continue
        typ = norm_type(sh.get("type") or get("type"))
        if typ == "void":
            records.append(make_record(num, typ, None, None, ""))
            continue
        wel = sh.find("weight")
        unit = None
        raw = None
        if wel is not None:
            raw = wel.text
            unit = norm_unit(wel.get("unit"))
        else:
            raw = sh.get("weight")
            unit = norm_unit(sh.get("weight-unit") or sh.get("unit"))
        unit = unit or root_unit or BASE_UNIT["central"]
        kg = parse_weight(raw, unit) if raw is not None else None
        month = parse_ship_month(get("shipped"), "iso")
        status = norm_status(get("status"))
        records.append(make_record(num, typ, month, kg, status))
    return seq, records


def parse_json(text):
    seq = None
    records = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line, parse_float=Decimal)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if "id" not in o and isinstance(o.get("meta"), dict):
                if seq is None:
                    try:
                        seq = int(o["meta"].get("seq"))
                    except (TypeError, ValueError):
                        pass
                continue
            num = shipment_number(str(o.get("id", "")))
            if num is None:
                continue
            typ = norm_type(o.get("kind"))
            if typ == "void":
                records.append(make_record(num, typ, None, None, ""))
                continue
            kg = None
            for k, val in o.items():
                if k.lower().startswith("weight"):
                    m = re.match(r"^weight[_\-]?(\w+)?$", k, re.I)
                    unit = norm_unit(m.group(1)) if m and m.group(1) else None
                    kg = parse_weight(str(val), unit or o.get("unit") and norm_unit(o["unit"])
                                      or BASE_UNIT["north"])
                    break
            month = parse_ship_month(o.get("shipped_at") or o.get("shipped"), "iso")
            records.append(make_record(num, typ, month, kg, norm_status(str(o.get("status", "")))))
    return seq, records


def parse_file(depot, path):
    data = read_bytes(path)
    if depot == "central" or data.lstrip()[:5] == b"<?xml" or data.lstrip()[:1] == b"<":
        return parse_xml(data)
    text = decode_text(data)
    if depot == "south":
        return parse_fixed(text)
    if depot == "north":
        return parse_json(text)
    if depot in DELIM:
        return parse_delimited(depot, text)
    raise ValueError("unknown depot " + depot)


# ---------------------------------------------------------------- main logic

def quant2(fr):
    d = Decimal(fr.numerator) / Decimal(fr.denominator) if False else None
    # exact rounding half up on the rational value
    sign = -1 if fr < 0 else 1
    scaled = abs(fr) * 100
    q = scaled.numerator // scaled.denominator
    rem = scaled - q
    if rem >= Fraction(1, 2):
        q += 1
    return float(Decimal(sign * q).scaleb(-2))


def main(data_dir, out_file):
    files = []
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if os.path.isfile(p):
            files.append((name.split("-", 1)[0].lower(), name, p))

    depots = sorted({f[0] for f in files})
    exports = {d: [] for d in depots}
    for depot, name, p in files:
        try:
            seq, recs = parse_file(depot, p)
        except Exception as e:  # keep going; report on stderr
            print("warning: cannot read %s: %s" % (name, e), file=sys.stderr)
            continue
        exports[depot].append((seq if seq is not None else -1, name, recs))

    corrections = 0
    resends = 0
    current = {}  # depot -> {num: record}
    for depot in depots:
        cur = {}
        for seq, name, recs in sorted(exports[depot], key=lambda e: (e[0], e[1])):
            for r in recs:
                n = r["num"]
                if r["type"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "correction":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur

    rank = {d: i for i, d in enumerate(HANDOVER_ORDER)}
    owners = {}
    for depot in sorted(depots, key=lambda d: (rank.get(d, len(rank)), d)):
        for n in current[depot]:
            owners.setdefault(n, []).append(depot)
    handovers = sum(1 for v in owners.values() if len(v) > 1)

    dep_tot = {d: [0, Fraction(0)] for d in depots}
    mon_tot = {}
    for n, owner_list in owners.items():
        depot = owner_list[0]
        r = current[depot][n]
        if r["status"] not in COUNTED or r["kg"] is None or r["month"] is None:
            continue
        dep_tot[depot][0] += 1
        dep_tot[depot][1] += r["kg"]
        key = "%04d-%02d" % r["month"]
        t = mon_tot.setdefault(key, [0, Fraction(0)])
        t[0] += 1
        t[1] += r["kg"]

    out = {
        "depots": {d: {"shipments": dep_tot[d][0], "total_kg": quant2(dep_tot[d][1])}
                   for d in depots},
        "months": {k: {"shipments": mon_tot[k][0], "total_kg": quant2(mon_tot[k][1])}
                   for k in sorted(mon_tot)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    os.makedirs(os.path.dirname(os.path.abspath(out_file)), exist_ok=True)
    with open(out_file, "w") as f:
        json.dump(out, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("usage: summarize.py DATA_DIR OUT_FILE", file=sys.stderr)
        sys.exit(2)
    main(sys.argv[1], sys.argv[2])

